# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Sequence, Tuple

from rosterkit.models import Student

Cells = Tuple[str, str, str]


def _check(people: Sequence[Student]) -> None:
    if not people:
        raise ValueError("no students for contact sheet")
    for person in people:
        if not person.email:
            raise ValueError(
                f"no email for {person.display_name}"
            )


def _by_name(person: Student) -> str:
    return person.display_name


def _widths(rows: Sequence[Cells]) -> List[int]:
    return [max(len(row[index]) for row in rows)
            for index in range(3)]


def _line(row: Cells, widths: Sequence[int]) -> str:
    pairs = zip(row, widths)
    cells = [f"{text:<{wide}}" for text, wide in pairs]
    return "  ".join(cells).rstrip()


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    people = sorted(students, key=_by_name)
    _check(people)
    rows = [(item.display_name, item.section, item.email)
            for item in people]
    widths = _widths(rows)
    return [_line(row, widths) for row in rows]

