# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.contacts import contact_rows


def make(last, first, section, email):
    return Student("1", last, first, section, email)


YOUNG = make("Young", "Zed", "B", "z@x.org")
ABBOTT = make("Abbott", "Amy", "A", "amy@x.org")
EXPECTED = [
    "Abbott, Amy  A  amy@x.org",
    "Young, Zed   B  z@x.org"
]


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_and_aligned(self):
        rows = contact_rows([YOUNG, ABBOTT])
        self.assertEqual(rows, EXPECTED)

    def test_missing_email_names_student(self):
        nobody = make("Lee", "Kim", "A", None)
        with self.assertRaises(ValueError) as caught:
            contact_rows([ABBOTT, nobody])
        self.assertIn("Lee, Kim", str(caught.exception))

    def test_empty_email_is_missing(self):
        with self.assertRaises(ValueError):
            contact_rows([make("Lee", "Kim", "A", "")])

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
